import axios from 'axios';
import { environment } from 'src/environments/environment';
import * as i0 from "@angular/core";
export class ItemService {
    constructor() { }
    async save(itemDto) {
        await axios.post(environment.api_url + 'item', itemDto);
    }
    /*async filterSearch(search: String): Promise<ItemDto[]> {
      const reponse = await axios.get(environment.api_url + 'item/teste');
      return reponse.data;
    }*/
    async filterSearch(search) {
        const response = await axios.get(`${environment.api_url}/filter-search`, {
            params: { search }
        });
        return response.data;
    }
    async findAll() {
        const reponse = await axios.get(environment.api_url + 'item');
        return reponse.data;
    }
    searchParamsBuilder(search) {
        const options = {
            search: search,
        };
        return options;
    }
}
